const disableAgentA2AEndpointsForMemberRevocation = `-- name: DisableAgentA2AEndpointsForMemberRevocation :many
UPDATE agent_a2a_endpoint endpoint
SET enabled = FALSE,
    updated_at = now()
WHERE endpoint.id = ANY($1::uuid[])
RETURNING endpoint.id
`

func (q *Queries) DisableAgentA2AEndpointsForMemberRevocation(ctx context.Context, endpointIds []pgtype.UUID) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, disableAgentA2AEndpointsForMemberRevocation, endpointIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

